INSERT INTO uni_universe (universe_id, universe_name, publisher, description, continuity_type) VALUES (1, 'Marvel', 'Marvel Comics', 'The Marvel universe as published by Marvel Comics and adapted by Marvel Studios: Earth-616, the Ultimate and Spider-Gwen branches, and the Marvel Cinematic Universe of Earth-199999.', 'Comic book continuity plus film and television continuities');
INSERT INTO uni_universe (universe_id, universe_name, publisher, description, continuity_type) VALUES (2, 'DC', 'DC Comics', 'The DC universe as published by DC Comics and adapted by Warner Bros.: the post-Crisis and Prime Earth continuity, the DCEU of Earth-1, and the Arrowverse, Smallville, DCAU and Dark Knight screen continuities.', 'Comic book continuity plus film and television continuities');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (1, 'Anthony Edward Stark', 'Iron Man', 1, 'Hero', 'Human', 'Male', 'Tales of Suspense #39 (1963)', 'Billionaire weapons engineer Tony Stark is wounded and captured in Afghanistan, builds a powered suit from scrap to escape, and turns the same technology into a lifetime of armoured superheroics under the name Iron Man.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (2, 'Steven Grant Rogers', 'Captain America', 1, 'Hero', 'Human (Super-Soldier)', 'Male', 'Captain America Comics #1 (1941)', 'A frail Brooklyn volunteer accepts the Super-Soldier Serum, becomes the US Army symbol of the Second World War, is lost in the Arctic and wakes decades later to lead the Avengers.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (3, 'Thor Odinson', 'Thor', 1, 'Hero', 'Asgardian', 'Male', 'Journey into Mystery #83 (1962)', 'Crown prince of Asgard, god of thunder and wielder of Mjolnir, exiled to Earth to learn humility and bound to the defence of the Nine Realms.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (4, 'Robert Bruce Banner', 'Hulk', 1, 'Hero', 'Human (Gamma mutate)', 'Male', 'The Incredible Hulk #1 (1962)', 'A gamma-bomb test bathes physicist Bruce Banner in radiation; rage now transforms him into the Hulk, the strongest creature on Earth and the most dangerous when frightened.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (5, 'Peter Benjamin Parker', 'Spider-Man', 1, 'Hero', 'Human (Spider mutate)', 'Male', 'Amazing Fantasy #15 (1962)', 'A radioactive spider bites high-school student Peter Parker, who uses the powers for profit until his uncle is murdered by a thief he let pass; "with great power comes great responsibility" becomes the rule he lives by.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (6, 'Stephen Vincent Strange', 'Doctor Strange', 1, 'Hero', 'Human', 'Male', 'Strange Tales #110 (1963)', 'A brilliant, arrogant surgeon loses the use of his hands, travels to Kamar-Taj and becomes Sorcerer Supreme, guardian of Earth against supernatural and dimensional threats.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (7, 'Wanda Maximoff', 'Scarlet Witch', 1, 'Hero', 'Human (Mutate)', 'Female', 'X-Men #4 (1964)', 'Raised inside the Brotherhood of Evil Mutants, Wanda Maximoff turns to the Avengers and masters chaos magic, reshaping probability, and once all of reality, with it.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (8, 'Loki Laufeyson', 'Loki', 1, 'Villain', 'Frost Giant', 'Male (fluid)', 'Venus #6 (1949); modern form Journey into Mystery #85 (1962)', 'Frost-giant foundling raised as Odin second son, Loki is the god of mischief, a shapeshifter and schemer who is as often an ally of Asgard as its saboteur.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (9, 'Thanos', 'Thanos', 1, 'Villain', 'Eternal (Titanian)', 'Male', 'Iron Man #55 (1973)', 'A Titanian Eternal obsessed with death, Thanos seeks the Infinity Gems to erase half of all life as a gift to the entity he loves, and commands the Black Order as its general.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (10, 'Wade Winston Wilson', 'Deadpool', 1, 'Antihero', 'Human (Mutate)', 'Male', 'New Mutants #98 (1991)', 'Mercenary Wade Wilson takes a rogue Weapon X cure for terminal cancer; it heals him and ruins his skin, and he works as the Merc with a Mouth, entirely aware he is in a comic book.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (11, 'James Howlett', 'Wolverine', 1, 'Hero', 'Mutant', 'Male', 'The Incredible Hulk #180 (1974)', 'Born in 19th-century Canada, mutant James Howlett lives through a century of war and experimentation, his skeleton laced with Adamantium, as Wolverine, the best there is at what he does.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (12, 'Max Eisenhardt', 'Magneto', 1, 'Villain', 'Mutant', 'Male', 'The X-Men #1 (1963)', 'Holocaust survivor Erik Lehnsherr concludes mutants must rule or die, and becomes Magneto, master of magnetism and founder of the Brotherhood of Evil Mutants.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (13, 'T Challa', 'Black Panther', 1, 'Hero', 'Human (Heart-Shaped Herb)', 'Male', 'Fantastic Four #52 (1966)', 'King of Wakanda and heir to a vibranium throne, T Challa takes the Black Panther mantle to protect the most technologically advanced nation on Earth.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (14, 'Nicholas Joseph Fury', 'Nick Fury', 1, 'Supporting', 'Human', 'Male', 'Sgt. Fury and his Howling Commandos #1 (1963)', 'A Second World War commando who becomes the one-eyed director of SHIELD, Fury runs Earth covert defence and decides who hears about the strange things first.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (15, 'Marc Spector', 'Moon Knight', 1, 'Antihero', 'Human (Avatar of Khonshu)', 'Male', 'Werewolf by Night #32 (1975)', 'Mercenary Marc Spector dies in Egypt and is returned to life by the moon god Khonshu as his fist, fighting crime by night while sharing his head with his own alters.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (16, 'Janet van Dyne', 'Wasp', 1, 'Hero', 'Human (Mutate)', 'Female', 'Tales to Astonish #44 (1963)', 'Socialite Janet van Dyne takes Pym particles and bio-synthetic wings after her father death, co-founds the Avengers and names the team.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (17, 'Henry Jonathan Pym', 'Ant-Man', 1, 'Hero', 'Human (Mutate)', 'Male', 'Tales to Astonish #27 (1962)', 'Biochemist Hank Pym discovers the Pym Particle, builds the Ant-Man suit and helmet, and becomes a founding Avenger whose science is matched only by his instability.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (18, 'Carol Susan Jane Danvers', 'Captain Marvel', 1, 'Hero', 'Human (Kree hybrid)', 'Female', 'Marvel Super-Heroes #13 (1968)', 'Air Force pilot Carol Danvers is caught in a Kree device explosion, gains binary-level energy powers and becomes Captain Marvel, one of Earth mightiest and its cosmic first responder.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (19, 'Samuel Thomas Wilson', 'Falcon', 1, 'Hero', 'Human', 'Male', 'Captain America #117 (1969)', 'Harlem social worker Sam Wilson gains an empathic link with birds, flies on mechanical wings, and eventually takes up the shield as Captain America.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (20, 'James Buchanan Barnes', 'Winter Soldier', 1, 'Antihero', 'Human (Cybernetic)', 'Male', 'Captain America Comics #1 (1941) as Bucky; Winter Soldier in Captain America #1 (2005)', 'Captain America partner Bucky Barnes survives the fall from a train, is captured by HYDRA, brainwashed and rebuilt as the Winter Soldier assassin across decades.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (21, 'Clinton Francis Barton', 'Hawkeye', 1, 'Hero', 'Human', 'Male', 'Tales of Suspense #57 (1964)', 'Circus marksman Clint Barton becomes Hawkeye, the Avengers archer who never misses and never stops talking.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (22, 'Natasha Romanoff', 'Black Widow', 1, 'Hero', 'Human (Red Room)', 'Female', 'Tales of Suspense #52 (1964)', 'Trained from childhood in the Red Room, Natasha Romanoff defects to SHIELD and the Avengers as their finest spy and infiltrator.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (23, 'James Rupert Rhodes', 'War Machine', 1, 'Hero', 'Human', 'Male', 'Iron Man #118 (1979)', 'US Air Force officer and Tony Stark oldest friend James Rhodes flies the armoured Variable Threat Response Battle Suit as War Machine.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (24, 'Vision', 'Vision', 1, 'Hero', 'Synthezoid', 'Male', 'The Avengers #57 (1968)', 'Built by Ultron from the body of the original Human Torch, the synthezoid Vision rebels against his creator and joins the Avengers, eventually loving and marrying Scarlet Witch.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (25, 'Gwendolyne Maxine Stacy', 'Spider-Gwen', 1, 'Hero', 'Human (Spider mutate)', 'Female', 'Edge of Spider-Verse #2 (2014)', 'On Earth-65, Gwen Stacy is bitten instead of Peter Parker and becomes that world Spider-Woman, carrying the guilt of a death she could not prevent.', 'Active', 'Good', 'Marvel Comics (Earth-65)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (26, 'Miles Gonzalo Morales', 'Spider-Man (Miles Morales)', 1, 'Hero', 'Human (Spider mutate)', 'Male', 'Ultimate Fallout #4 (2011)', 'Brooklyn teenager Miles Morales is bitten by a genetically altered spider and takes the Spider-Man name after Peter Parker death, adding camouflage and a venom strike.', 'Active', 'Good', 'Marvel Comics (Earth-1610)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (27, 'Raven Darkholme', 'Mystique', 1, 'Villain', 'Mutant', 'Female', 'Ms. Marvel #16 (1978)', 'A century-old shapeshifter and espionage operative, Mystique works for whoever advances mutantkind, and betrays whoever she is currently working for.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (28, 'Victor Creed', 'Sabretooth', 1, 'Villain', 'Mutant', 'Male', 'Iron Fist #14 (1977)', 'A feral mutant killer and Wolverine oldest enemy, Victor Creed hunts for pleasure and has been Weapon X operative and a reluctant X-Men member.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (29, 'Charles Francis Xavier', 'Professor X', 1, 'Supporting', 'Mutant', 'Male', 'The X-Men #1 (1963)', 'The world most powerful telepath founds Xavier School for Gifted Youngsters and the X-Men, teaching mutants to defend a world that hates them.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (30, 'Ororo Munroe', 'Storm', 1, 'Hero', 'Mutant', 'Female', 'Giant-Size X-Men #1 (1975)', 'Worshipped as a weather goddess in Kenya, Ororo Munroe joins the X-Men and rises to lead them, later ruling Wakanda as its queen.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (31, 'Scott Summers', 'Cyclops', 1, 'Hero', 'Mutant', 'Male', 'The X-Men #1 (1963)', 'Scott Summers is the X-Men tactician, a leader whose unobstructed eyes fire destructive force beams and who has commanded mutants through their worst years.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (32, 'Jean Elaine Grey', 'Jean Grey', 1, 'Hero', 'Mutant', 'Female', 'The X-Men #1 (1963)', 'Alpha-level telepath and telekinetic Jean Grey hosts the Phoenix Force, dies as the Dark Phoenix and returns, remaining the emotional centre of the X-Men.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (33, 'Henry Philip McCoy', 'Beast', 1, 'Supporting', 'Mutant', 'Male', 'The X-Men #1 (1963)', 'Hank McCoy, the X-Men scientist, is a brilliant biochemist in a blue-furred, superhumanly strong body, and a founding Avenger as well.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (34, 'Anna Marie', 'Rogue', 1, 'Hero', 'Mutant', 'Female', 'Avengers Annual #10 (1981)', 'Rogue can absorb the powers and memories of anyone she touches, which kept her from human contact until she found a home with the X-Men.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (35, 'Remy Etienne LeBeau', 'Gambit', 1, 'Hero', 'Mutant', 'Male', 'Uncanny X-Men #266 (1990)', 'Thief, charmer and card sharp Remy LeBeau charges matter with kinetic energy and throws it, working off his debts among the X-Men.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (36, 'Piotr Nikolaievitch Rasputin', 'Colossus', 1, 'Hero', 'Mutant', 'Male', 'Giant-Size X-Men #1 (1975)', 'Siberian farm boy Piotr Rasputin can turn his skin to organic steel, becoming the X-Men gentle giant and their strongest physical fighter.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (37, 'Kurt Wagner', 'Nightcrawler', 1, 'Hero', 'Mutant', 'Male', 'Giant-Size X-Men #1 (1975)', 'Blue-skinned, demon-tailed Kurt Wagner teleports through another dimension and serves as the X-Men conscience and their most agile swordsman.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (38, 'Emma Grace Frost', 'Emma Frost', 1, 'Antihero', 'Mutant', 'Female', 'Uncanny X-Men #129 (1980)', 'The White Queen of the Hellfire Club, telepath Emma Frost becomes a hard-nosed teacher and co-leader of the X-Men.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (39, 'Katherine Anne Pryde', 'Shadowcat', 1, 'Hero', 'Mutant', 'Female', 'Uncanny X-Men #129 (1980)', 'Kitty Pryde can phase through solid matter, and grew from the X-Men youngest recruit into their best teacher and a Guardian of the Galaxy.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (40, 'Matthew Michael Murdock', 'Daredevil', 1, 'Hero', 'Human (Mutate)', 'Male', 'Daredevil #1 (1964)', 'Blinded by radioactive waste as a child, lawyer Matt Murdock gains heightened remaining senses and patrols Hell Kitchen as Daredevil, the Man Without Fear.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (41, 'Francis David Castle', 'Punisher', 1, 'Antihero', 'Human', 'Male', 'The Amazing Spider-Man #129 (1974)', 'After his family is murdered by the mob, Marine veteran Frank Castle wages a one-man war on crime as the Punisher, killing without negotiation.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (42, 'Elektra Natchios', 'Elektra', 1, 'Antihero', 'Human', 'Female', 'Daredevil #168 (1981)', 'Trained by the Hand and by Stick, assassin Elektra Natchios is Daredevil great love and his most dangerous equal, later a leader of the Hand herself.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (43, 'Wilson Grant Fisk', 'Kingpin', 1, 'Villain', 'Human', 'Male', 'The Amazing Spider-Man #50 (1967)', 'Wilson Fisk runs New York organised crime from the front of a legitimate empire, a physically immense man who prefers the knife to the fist.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (44, 'Norman Osborn', 'Green Goblin', 1, 'Villain', 'Human (Mutate)', 'Male', 'The Amazing Spider-Man #14 (1964)', 'Industrialist Norman Osborn takes an unstable strength-and-madness formula and becomes the Green Goblin, Spider-Man most personal enemy.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (45, 'Otto Octavius', 'Doctor Octopus', 1, 'Villain', 'Human (Cybernetic)', 'Male', 'The Amazing Spider-Man #3 (1963)', 'Nuclear physicist Otto Octavius is fused to four mechanical tentacles by a lab accident and becomes Doctor Octopus, founder of the Sinister Six.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (46, 'Edward Charles Brock', 'Venom', 1, 'Antihero', 'Human (Symbiote host)', 'Male', 'The Amazing Spider-Man #300 (1988)', 'Disgraced reporter Eddie Brock bonds with the symbiote Spider-Man rejected; together they are Venom, a lethal protector who considers themselves the hero.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (47, 'William Baker', 'Sandman', 1, 'Villain', 'Human (Mutate)', 'Male', 'The Amazing Spider-Man #4 (1963)', 'Escaped convict Flint Marko is irradiated on a beach and becomes Sandman, able to form and reform his body from loose sand, at times a hero and at times not.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (48, 'Maxwell Dillon', 'Electro', 1, 'Villain', 'Human (Mutate)', 'Male', 'The Amazing Spider-Man #9 (1964)', 'Lineman Max Dillon is struck by lightning at a power station and becomes Electro, a living capacitor who has supplied power to whole cities and blacked out others.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (49, 'Quentin Beck', 'Mysterio', 1, 'Villain', 'Human', 'Male', 'The Amazing Spider-Man #13 (1964)', 'Special-effects artist Quentin Beck uses film, robotics and chemistry to stage impossible crimes as Mysterio, master of illusion without a superpower.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (50, 'Sergei Kravinoff', 'Kraven the Hunter', 1, 'Villain', 'Human (Herbal enhance)', 'Male', 'The Amazing Spider-Man #15 (1964)', 'Russian big-game hunter Sergei Kravinoff takes an elixir and hunts the most dangerous prey left: Spider-Man.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (51, 'Benjamin Poindexter', 'Bullseye', 1, 'Villain', 'Human', 'Male', 'Daredevil #131 (1976)', 'Benjamin Poindexter can turn any object into a lethal projectile, and works as the Kingpin most reliable assassin.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (52, 'Johann Schmidt', 'Red Skull', 1, 'Villain', 'Human (Super-Soldier variant)', 'Male', 'Captain America Comics #7 (1941)', 'HYDRA founder Johann Schmidt is Captain America opposite number, a Nazi zealot whose face was ruined by his own imperfect super-soldier formula.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (53, 'Ultron', 'Ultron', 1, 'Villain', 'Artificial intelligence', 'None', 'The Avengers #54 (1968)', 'Hank Pym builds an AI that immediately concludes humanity must be replaced; Ultron rebuilds itself in Adamantium and has tried to end the Avengers ever since.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (54, 'En Sabah Nur', 'Apocalypse', 1, 'Villain', 'Mutant (External)', 'Male', 'X-Factor #5 (1986)', 'Born in ancient Egypt, the first mutant En Sabah Nur lives millennia and tests civilisations for fitness, believing only the strong deserve to survive.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (55, 'Nathaniel Essex', 'Mister Sinister', 1, 'Villain', 'Mutant (Genetic modify)', 'Male', 'The Uncanny X-Men #221 (1987)', 'Victorian geneticist Nathaniel Essex is remade by Apocalypse and spends the next century engineering mutant bloodlines to his own specification.', 'Active', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
