INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (165, 'James Buchanan Barnes', 'Winter Soldier (MCU)', 1, 'Antihero', 'Human (Cybernetic)', 'Male', 'Captain America: The First Avenger (2011 film)', 'Bucky Barnes falls from a train, is taken by HYDRA and used as the Winter Soldier for seventy years before Steve Rogers refuses to give up on him.', 'Active', 'Neutral', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (166, 'Wanda Maximoff', 'The Scarlet Witch (MCU)', 1, 'Hero', 'Human (Experiment-enhanced)', 'Female', 'WandaVision (2021 miniseries)', 'In Westview, Wanda creates the Scarlet Witch persona, a sitcom reality built from grief, and steps out of it into the role the Darkhold predicted.', 'Active', 'Neutral', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (167, 'Marc Spector', 'Moon Knight (MCU)', 1, 'Antihero', 'Human (Avatar of Khonshu)', 'Male', 'Moon Knight (2022 miniseries)', 'The MCU Marc Spector shares a body with Steven Grant and a debt with Khonshu, and neither of his alters is in control of the arrangement.', 'Active', 'Neutral', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (168, 'N Jadaka', 'Killmonger', 1, 'Villain', 'Human', 'Male', 'Black Panther (2018 film)', 'Erik Stevens grows up outside Wakanda with the memory of a murdered father and takes the throne to force the country to arm the world.', 'Deceased', 'Evil', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (169, 'Hela Odinsdottir', 'Hela (MCU)', 1, 'Villain', 'Asgardian (Death goddess)', 'Female', 'Thor: Ragnarok (2017 film)', 'Odin firstborn and executioner returns from exile to take Asgard, and destroys Mjolnir on arrival to make the point.', 'Deceased', 'Evil', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (170, 'Ultron', 'Ultron (MCU)', 1, 'Villain', 'Artificial intelligence', 'None', 'The Avengers: Age of Ultron (2015 film)', 'Built by Stark and Banner to protect Earth, the MCU Ultron decides the only path to peace is extinction and lifts a city to prove it.', 'Deceased', 'Evil', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (171, 'Kal-El / Clark Joseph Kent', 'Superman (DCEU)', 2, 'Hero', 'Kryptonian', 'Male', 'Man of Steel (2013 film)', 'The DCEU Kal-El is a loner learning restraint from a father who died for it, dies to Doomsday and returns to lead the final battle.', 'Active', 'Good', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (172, 'Bruce Wayne', 'Batman (DCEU)', 2, 'Hero', 'Human', 'Male', 'Batman v Superman: Dawn of Justice (2016 film)', 'The DCEU Bruce Wayne has stopped asking whether he should kill, and the Justice League is what pulls him back towards the line he used to hold.', 'Active', 'Good', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (173, 'Diana Prince', 'Wonder Woman (DCEU)', 2, 'Hero', 'Amazon (Demi-god)', 'Female', 'Batman v Superman: Dawn of Justice (2016 film)', 'Diana of Themyscira fights through the First World War, withdraws from humanity and returns when the Justice League needs the argument for hope.', 'Active', 'Good', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (174, 'Bartholomew Henry Allen', 'The Flash (DCEU)', 2, 'Hero', 'Human (Speed Force conduit)', 'Male', 'Batman v Superman: Dawn of Justice (2016 film, cameo)', 'Forensic accountant Barry Allen is struck by lightning, gains the Speed Force, and keeps breaking his own rules about not undoing the past.', 'Active', 'Good', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (175, 'Arthur Joseph Curry', 'Aquaman (DCEU)', 2, 'Hero', 'Atlantean (Human hybrid)', 'Male', 'Batman v Superman: Dawn of Justice (2016 film, cameo)', 'The DCEU Arthur Curry wants nothing to do with Atlantis until his half-brother starts a war, and then takes the throne to stop it.', 'Active', 'Good', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (176, 'Victor Stone', 'Cyborg (DCEU)', 2, 'Hero', 'Human (Cybernetic)', 'Male', 'Batman v Superman: Dawn of Justice (2016 film, cameo)', 'A Mother Box rebuilds Victor Stone after a car crash, and the DCEU Cyborg spends the war refusing to call himself a man.', 'Active', 'Good', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (177, 'Harleen Frances Quinzel', 'Harley Quinn (DCEU)', 2, 'Antihero', 'Human', 'Female', 'Suicide Squad (2016 film)', 'The DCEU Harley Quinn survives a chemical vat, an exploding collar and a break-up, and settles into being exactly who she is.', 'Active', 'Neutral', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (178, 'Floyd Lawton', 'Deadshot (DCEU)', 2, 'Villain', 'Human', 'Male', 'Suicide Squad (2016 film)', 'The DCEU Floyd Lawton kills for contract and works Task Force X for a chance to see his daughter, and cannot miss either way.', 'Active', 'Neutral', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (179, 'Unknown', 'Joker (DCEU)', 2, 'Villain', 'Human', 'Male', 'Suicide Squad (2016 film)', 'This Joker is a Gotham kingpin draped in tattoos who owns half the city and treats Harley as property he intends to collect.', 'Active', 'Evil', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (180, 'Amanda Blake Waller', 'Amanda Waller (DCEU)', 2, 'Supporting', 'Human', 'Female', 'Suicide Squad (2016 film)', 'A.R.G.U.S. director Amanda Waller decides what the nation cannot afford to know, and assembles a squad of convicts as the deniable answer.', 'Active', 'Neutral', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (181, 'Mera', 'Mera (DCEU)', 2, 'Supporting', 'Atlantean', 'Female', 'Justice League (2017 film)', 'Mera of Xebel is a warrior-queen in waiting who would rather fight a war of succession than watch Atlantis take the surface.', 'Active', 'Good', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (182, 'Orm Marius', 'Ocean Master (DCEU)', 2, 'Villain', 'Atlantean', 'Male', 'Aquaman (2018 film)', 'Orm, king of Atlantis in his own estimation, declares war on the surface after the humans refuse to stop poisoning the sea.', 'Deposed', 'Evil', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (183, 'Steppenwolf', 'Steppenwolf (DCEU)', 2, 'Villain', 'New God', 'Male', 'Justice League (2017 film)', 'Darkseid uncle and general reunites the Mother Boxes to open the way for Apokolips, and loses because the League arrives at all.', 'Deceased', 'Evil', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (184, 'Marisol Vega', 'Antares', 1, 'Hero', 'Human (Stellar-graft)', 'Female', NULL, 'Original addition — a Manila-born astronomer whose experimental stellar-graft lets her bend local gravity and see the sky as a map. Written for this demonstration, not from Marvel publication.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Original addition');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (185, 'Vaani Prasad', 'Silica', 2, 'Hero', 'Human (Silicon symbiont)', 'Female', NULL, 'Original addition — a Bhubaneswar software engineer bonded to a silicon-based symbiont that lets her weave temporary machines from loose matter. Written for this demonstration, not from DC publication.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Original addition');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (186, 'Ruth Anand', 'Quiet Hour', 2, 'Villain', 'Human (Chronal accident)', 'Female', NULL, 'Original addition — a night-shift archivist caught in a chronal accident who can freeze a room for ten seconds. Written for this demonstration, not from DC publication.', 'Active', 'Evil', 'DC Comics (New Earth/Prime Earth)', 'Original addition');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (187, 'Tomas Oyelaran', 'Ferro', 1, 'Hero', 'Human (Ferro-kinetic)', 'Male', NULL, 'Original addition — a Lagos welder and union organiser who can reshape ferrous metal on contact, and refuses the corporate contracts that follow. Written for this demonstration, not from Marvel publication.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Original addition');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (188, 'Ada Nwafor', 'Lumen', 2, 'Supporting', 'Human (Light-born)', 'Female', NULL, 'Original addition — an Ivorian photojournalist whose light-born body lets her pass through walls and film what no camera can see. Written for this demonstration, not from DC publication.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Original addition');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (189, 'Cassandra Mele', 'Cassandra', 1, 'Cosmic Entity', 'Cosmic entity', 'Female', NULL, 'Original addition — a precognitive entity who speaks in statistically weighted probabilities and refuses to say which futures are certain. Written for this demonstration, not from Marvel publication.', 'Unknown', 'Neutral', 'Marvel Comics (Earth-616)', 'Original addition');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (190, 'Reed Richards', 'Mister Fantastic', 1, 'Hero', 'Human (Mutate)', 'Male', 'Fantastic Four #1 (1961)', 'Cosmic rays during an unauthorised space flight give Reed Richards a body that stretches without limit, and a mind that will not stop testing the universe.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (191, 'Susan Storm Richards', 'Invisible Woman', 1, 'Hero', 'Human (Mutate)', 'Female', 'Fantastic Four #1 (1961)', 'Sue Storm bends light around herself and projects force fields, and is the member of the Fantastic Four who actually holds the family together.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (192, 'Jonathan Lowell Spencer Storm', 'Human Torch', 1, 'Hero', 'Human (Mutate)', 'Male', 'Fantastic Four #1 (1961)', 'Johnny Storm covers himself in flame and flies, the youngest and loudest of the Fantastic Four.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (193, 'Benjamin Jacob Grimm', 'The Thing', 1, 'Hero', 'Human (Mutate)', 'Male', 'Fantastic Four #1 (1961)', 'Ben Grimm is turned into orange rock by the same cosmic rays that made the rest of the team, and spends the rest of his life being the strongest one there is.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (194, 'Blackagar Boltagon', 'Black Bolt', 1, 'Hero', 'Inhuman', 'Male', 'Fantastic Four #45 (1965)', 'King of the Inhumans, Black Bolt cannot speak above a whisper without levelling a city, which makes him the quietest and most feared ruler in the Marvel universe.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (195, 'Medusalith Amaquelin', 'Medusa', 1, 'Hero', 'Inhuman', 'Female', 'Fantastic Four #36 (1965)', 'Medusa rules the Inhumans beside Black Bolt and commands her own living hair as a weapon and a second pair of hands.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (196, 'Crystalia Amaquelin', 'Crystal', 1, 'Hero', 'Inhuman', 'Female', 'Fantastic Four #45 (1965)', 'Crystal can summon the four elements, and has been an Avenger and a Fantastic Four member as well as Inhuman royalty.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (197, 'Karnak Mander-Azur', 'Karnak', 1, 'Supporting', 'Inhuman', 'Male', 'Fantastic Four #45 (1965)', 'Karnak sees the flaw in anything, and has spent his life finding the one weak point in every opponent and every structure.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (198, 'Gorgon Petragon', 'Gorgon', 1, 'Supporting', 'Inhuman', 'Male', 'Fantastic Four #44 (1965)', 'Gorgon commands the Inhuman royal guard and can shatter the ground with a single stomp of his hooves.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (199, 'Pietro Django Maximoff', 'Quicksilver', 1, 'Antihero', 'Human (Mutate)', 'Male', 'X-Men #4 (1964)', 'Pietro Maximoff moves at supersonic speed and has never once been patient about anything, working with the Brotherhood, the Avengers and himself in turn.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (200, 'Carl Lucas', 'Luke Cage', 1, 'Hero', 'Human (Experiment-enhanced)', 'Male', 'Hero for Hire #1 (1972)', 'Framed and imprisoned, Carl Lucas gains bulletproof skin in a prison experiment and becomes Luke Cage, Hero for Hire, and later an Avenger.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (201, 'Daniel Thomas Rand-Kai', 'Iron Fist', 1, 'Hero', 'Human (Chi channel)', 'Male', 'Marvel Premiere #15 (1974)', 'Danny Rand returns from K un-Lun with the chi of Shou-Lao in his fist, able to strike with force that can break a helicopter.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (202, 'Jessica Campbell Jones', 'Jessica Jones', 1, 'Antihero', 'Human (Experiment-enhanced)', 'Female', 'Alias #1 (2001)', 'Former superhero Jewel quits the costume after a period of control by the Purple Man and becomes a private investigator, which is mostly the same job with worse pay.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (203, 'Jason Peter Garrick', 'The Flash (Jay Garrick)', 2, 'Hero', 'Human (Speed Force conduit)', 'Male', 'Flash Comics #1 (1940)', 'Jay Garrick inhales hard water fumes, gains super speed and becomes the original Flash, the grandfather of every speedster who follows.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (204, 'Carter Hall', 'Hawkman', 2, 'Hero', 'Human (reincarnated)', 'Male', 'Flash Comics #1 (1940)', 'Carter Hall is the latest reincarnation of the Egyptian prince Khufu, reborn with wings and a mace and an endless war beside Hawkgirl.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (205, 'Alan Scott', 'Green Lantern (Alan Scott)', 2, 'Hero', 'Human (Starheart)', 'Male', 'All-American Comics #16 (1940)', 'Alan Scott wields a ring forged from the Starheart, the original Green Lantern of Earth and a Justice Society founder.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (206, 'Theodore Grant', 'Wildcat', 2, 'Hero', 'Human', 'Male', 'Sensation Comics #1 (1942)', 'Ted Grant is a heavyweight boxing champion who fights crime under a cat mask and has trained half the martial artists in the DC universe.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (207, 'Helena Rosa Bertinelli', 'Huntress', 2, 'Antihero', 'Human', 'Female', 'The Huntress #1 (1989)', 'Helena Bertinelli survives her family murder and fights the mafia as Huntress, with less patience and more crossbow than Batman would like.', 'Active', 'Neutral', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (208, 'Barbara Ann Minerva', 'Cheetah', 2, 'Villain', 'Human (Cursed)', 'Female', 'Wonder Woman #6 (1943)', 'Archaeologist Barbara Ann Minerva is cursed by a plant god and becomes Cheetah, Wonder Woman oldest and fastest enemy.', 'Active', 'Evil', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (209, 'Doris Zeul', 'Giganta', 2, 'Villain', 'Human (Metahuman)', 'Female', 'Wonder Woman #9 (1944)', 'Doris Zeul can grow to a hundred feet, and uses the size to be exactly as large a problem as she wants to be.', 'Active', 'Evil', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (210, 'Samuel Scudder', 'Mirror Master', 2, 'Villain', 'Human', 'Male', 'Flash #105 (1959)', 'Sam Scudder moves through reflective surfaces as doorways and has trapped the Flash in a mirror more than once.', 'Active', 'Evil', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (211, 'Mark Mardon', 'Weather Wizard', 2, 'Villain', 'Human (Metahuman)', 'Male', 'Flash #110 (1959)', 'Mark Mardon controls weather with a wand built from his brother research, and storms are the only thing he has ever been good at.', 'Active', 'Evil', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (212, 'Steven Rockwell Trevor', 'Steve Trevor', 2, 'Supporting', 'Human', 'Male', 'All Star Comics #8 (1941)', 'Air Force officer Steve Trevor crashes on Themyscira, brings Diana into the world of men, and later runs A.R.G.U.S. field operations.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (213, 'Oliver Jonas Queen', 'Green Arrow (Arrow)', 2, 'Hero', 'Human', 'Male', 'Arrow (2012 television series)', 'Five years on an island turn playboy Oliver Queen into a hooded killer who has to learn, season by season, to become the hero Star City needs instead.', 'Active', 'Good', 'DC Comics (Arrowverse)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (214, 'Dinah Laurel Lance', 'Black Canary (Arrow)', 2, 'Hero', 'Human (Metahuman)', 'Female', 'Arrow (2012 television series)', 'Assistant DA by day and Black Canary by night, Dinah Lance fights for Star City in court and on the rooftops with the same argument.', 'Active', 'Good', 'DC Comics (Arrowverse)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (215, 'Felicity Megan Smoak', 'Felicity Smoak', 2, 'Supporting', 'Human', 'Female', 'Arrow (2012 television series)', 'IT specialist Felicity Smoak becomes Overwatch, the voice in Team Arrow ear and the person who actually understands the technology.', 'Active', 'Good', 'DC Comics (Arrowverse)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (216, 'T Challa', 'Black Panther (MCU)', 1, 'Hero', 'Human (Heart-Shaped Herb)', 'Male', 'Captain America: Civil War (2016 film)', 'The MCU T Challa takes the throne after his father death, hunts the Winter Soldier, and opens Wakanda to the world against every instinct he was raised with.', 'Active', 'Good', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (217, 'Carol Susan Jane Danvers', 'Captain Marvel (MCU)', 1, 'Hero', 'Human (Kree hybrid)', 'Female', 'Captain Marvel (2019 film)', 'Kree-blooded Air Force pilot Carol Danvers breaks free of her own conditioning and becomes the strongest Avenger, and the one who answers Fury pager.', 'Active', 'Good', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (218, 'Nebula', 'Nebula (MCU)', 1, 'Antihero', 'Luphomoid (Cybernetic)', 'Female', 'Guardians of the Galaxy (2014 film)', 'The MCU Nebula is Thanos daughter, rebuilt piece by piece after every loss, and the one who finally kills the version of herself who would serve him.', 'Active', 'Neutral', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (219, 'Mantis', 'Mantis (MCU)', 1, 'Hero', 'Human (Empathic)', 'Female', 'Guardians of the Galaxy Vol. 2 (2017 film)', 'Mantis can feel and change emotions with a touch, was raised by Ego to help him sleep, and joins the Guardians when she learns what she was for.', 'Active', 'Good', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (220, 'Matthew Michael Murdock', 'Daredevil (MCU)', 1, 'Hero', 'Human (Mutate)', 'Male', 'Daredevil (2015 television series)', 'The MCU Matt Murdock is a Hell Kitchen lawyer with a heightened hearing that functions as radar, and a hand that keeps finding itself on a doorknob.', 'Active', 'Good', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (221, 'Jessica Campbell Jones', 'Jessica Jones (MCU)', 1, 'Antihero', 'Human (Experiment-enhanced)', 'Female', 'Jessica Jones (2015 television series)', 'The MCU Jessica Jones survives Kilgrave, quits the costume and takes photographs for anyone who will pay, which is the same job with worse pay.', 'Active', 'Neutral', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (222, 'Carl Lucas', 'Luke Cage (MCU)', 1, 'Hero', 'Human (Experiment-enhanced)', 'Male', 'Jessica Jones (2015 television series)', 'The MCU Luke Cage is bulletproof, ex-convict and Harlem barbershop legend, and takes the neighbourhood as his jurisdiction.', 'Active', 'Good', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (223, 'Daniel Rand', 'Iron Fist (MCU)', 1, 'Hero', 'Human (Chi channel)', 'Male', 'Iron Fist (2017 television series)', 'The MCU Danny Rand comes back from K un-Lun fifteen years late, with a glowing fist and no idea how the family business works.', 'Active', 'Good', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (224, 'Ebony Maw', 'Ebony Maw', 1, 'Villain', 'Unknown (Black Order)', 'Male', 'Black Order #1 (2013); The Avengers: Infinity War (2018 film)', 'Thanos speaker and torturer, Ebony Maw talks his way into a mind and out of a trap, and treats cruelty as a form of rhetoric.', 'Deceased', 'Evil', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (225, 'Cull Obsidian', 'Cull Obsidian', 1, 'Villain', 'Unknown (Black Order)', 'Male', 'Black Order #1 (2013); The Avengers: Infinity War (2018 film)', 'Black Dwarf of the Black Order is the heavy assault arm: a wall of muscle with a hammer who exists to break a line.', 'Deceased', 'Evil', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (226, 'Proxima Midnight', 'Proxima Midnight', 1, 'Villain', 'Unknown (Black Order)', 'Female', 'Black Order #1 (2013); The Avengers: Infinity War (2018 film)', 'Proxima Midnight carries a spear that never misses, and is the precise half of the Black Order field pair.', 'Deceased', 'Evil', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (227, 'Corvus Glaive', 'Corvus Glaive', 1, 'Villain', 'Unknown (Black Order)', 'Male', 'Black Order #1 (2013); The Avengers: Infinity War (2018 film)', 'Corvus Glaive carries a glaive that can cut anything, and cannot be killed while it remains unbroken.', 'Deceased', 'Evil', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (228, 'Johann Schmidt', 'Red Skull (MCU)', 1, 'Villain', 'Human (Super-Soldier variant)', 'Male', 'Captain America: The First Avenger (2011 film)', 'HYDRA head Johann Schmidt takes an imperfect serum, loses his face to it, and ends up a wraith guarding the Soul Stone on Vormir.', 'Deceased (cursed)', 'Evil', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (229, 'Waylon Jones', 'Killer Croc (DCEU)', 2, 'Villain', 'Human (Metahuman reptile)', 'Male', 'Suicide Squad (2016 film)', 'The DCEU Waylon Jones is a sewer-dwelling cannibal with a crocodile hide, recruited for Task Force X because nobody will miss him.', 'Active', 'Evil', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (230, 'George Harkness', 'Captain Boomerang (DCEU)', 2, 'Villain', 'Human', 'Male', 'Suicide Squad (2016 film)', 'Digger Harkness throws boomerangs for a living and is the Squad most annoying member by a wide margin.', 'Deceased', 'Evil', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (231, 'Atlanna', 'Atlanna', 2, 'Supporting', 'Atlantean', 'Female', 'Aquaman (2018 film)', 'Queen Atlanna abandons the throne for a lighthouse keeper, is given to the Trench for it, and survives to see her son take the crown.', 'Active', 'Good', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (232, 'Veranke', 'Veranke', 1, 'Villain', 'Skrull', 'Female', 'New Avengers: Illuminati #1 (2006)', 'The Skrull queen Veranke takes the form of Jessica Drew and spends years inside the hero community, running the invasion from a position of trust.', 'Deceased', 'Evil', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (233, 'Sylvie Laufeydottir', 'Sylvie', 1, 'Antihero', 'Frost Giant', 'Female', 'Loki (2021 television series)', 'A Loki variant who escaped the TVA as a child and spent her life hunting the man who wrote the timeline, and finally made the choice he would not.', 'Active', 'Neutral', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (234, 'Dru-Zod', 'General Zod (DCEU)', 2, 'Villain', 'Kryptonian', 'Male', 'Man of Steel (2013 film)', 'The DCEU Zod was engineered to protect Krypton and, with the planet gone, decides the only way to do that is to rebuild it on top of Earth.', 'Deceased', 'Evil', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (235, 'He Who Remains', 'He Who Remains', 1, 'Villain', 'Human (31st century)', 'Male', 'Loki (2021 television series)', 'A scientist from the 31st century who won the first multiversal war, then pruned every branch to keep the peace, and was tired of the job when he was finally found.', 'Deceased', 'Neutral', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (236, 'Amanda Blake Waller', 'Amanda Waller', 2, 'Supporting', 'Human', 'Female', 'Legends #1 (1986)', 'The director who built Task Force X: Amanda Waller decides what the government cannot afford to admit it needs, and staffs the answer with people who have no choice.', 'Active', 'Neutral', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (237, 'Vision', 'Vision (MCU)', 1, 'Hero', 'Synthezoid', 'Male', 'The Avengers: Age of Ultron (2015 film)', 'Built from the Mind Stone and vibranium, the MCU Vision chooses the Avengers over his creator, loves Wanda, and dies twice for it.', 'Deceased', 'Good', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (238, 'David Hyde', 'Black Manta (DCEU)', 2, 'Villain', 'Human', 'Male', 'Aquaman (2018 film)', 'The DCEU David Hyde loses his father to Aquaman in a submarine fight and spends two films building the armour and the grudge to answer for it.', 'Active', 'Evil', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (239, 'Wong', 'Wong', 1, 'Supporting', 'Human', 'Male', 'Doctor Strange (2016 film)', 'The librarian of Kamar-Taj who becomes Sorcerer Supreme and then has to run a mystically destabilised world with a strategic reserve of magical talent.', 'Active', 'Good', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (240, 'Yondu Udonta', 'Yondu', 1, 'Antihero', 'Centaurian', 'Male', 'Marvel Super-Heroes #18 (1969)', 'A Centaurian Ravager captain who kept Peter Quill rather than delivering him, and has spent a lifetime making the choice look accidental.', 'Deceased', 'Neutral', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (241, 'Richard Rider', 'Nova', 1, 'Hero', 'Human (Nova Corps)', 'Male', 'Nova #1 (1976)', 'High-school student Richard Rider inherits the last Nova centurion suit and the entire Corps weight when Xandar falls.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (242, 'John Jonah Jameson', 'J. Jonah Jameson', 1, 'Supporting', 'Human', 'Male', 'The Amazing Spider-Man #1 (1963)', 'Daily Bugle editor who made Spider-Man a national argument, then spent years discovering the story was more complicated than the headline.', 'Active', 'Neutral', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (243, 'James Worthington Gordon', 'James Gordon', 2, 'Supporting', 'Human', 'Male', 'Detective Comics #27 (1939)', 'The Gotham police officer who decided the city could be saved and worked with a vigilante to prove it, eventually running the department that chased him.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (244, 'Perry White', 'Perry White', 2, 'Supporting', 'Human', 'Male', 'Superman #7 (1940)', 'The Daily Planet editor who holds a newsroom together with shouting and principle, and has been the closest thing Metropolis has to a conscience.', 'Active', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (245, 'Jor-El', 'Jor-El', 2, 'Supporting', 'Kryptonian', 'Male', 'Action Comics #1 (1938)', 'Krypton leading scientist, and the man the Science Council refused to believe, who saved his son instead of his planet.', 'Deceased', 'Good', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (246, 'Lincoln March', 'Lincoln March', 2, 'Villain', 'Human', 'Male', 'Batman #1 (2011)', 'A Gotham mayoral candidate who turns out to be the Court of Owls most successful experiment and the closest thing Bruce Wayne has to a brother.', 'Active', 'Evil', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (247, 'Hugo Strange', 'Hugo Strange', 2, 'Villain', 'Human', 'Male', 'Detective Comics #36 (1940)', 'The psychiatrist who treats Arkham as a laboratory, and once made a career of predicting who Batman was for the fun of it.', 'Active', 'Evil', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (248, 'The Ancient One', 'The Ancient One', 1, 'Supporting', 'Human (Sorcerer Supreme)', 'Female', 'Strange Tales #110 (1963)', 'Sorcerer Supreme of Kamar-Taj and Stephen Strange teacher, who borrowed more time than she was willing to tell anyone about.', 'Deceased', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (249, 'Carol Susan Jane Danvers', 'Ms. Marvel (Earth-616)', 1, 'Hero', 'Human (Kree hybrid)', 'Female', 'Marvel Super-Heroes #13 (1968)', 'The Earth-616 Carol Danvers spends years as Ms. Marvel before the title Binary and then Captain Marvel catch up with her, and holds Avengers Mansion when the Siege of Asgard comes looking for it.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (250, 'Adam Warlock', 'Adam Warlock', 1, 'Hero', 'Artificial human (Sovereign)', 'Male', 'Fantastic Four #66 (1967)', 'An engineered perfect human who ends up carrying the Soul Gem, which is what finally lets the Avengers do to the Infinity Gauntlet what force alone could not.', 'Active', 'Good', 'Marvel Comics (Earth-616)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (251, 'Tara Markov', 'Terra', 2, 'Villain', 'Human (Metahuman)', 'Female', 'New Teen Titans #26 (1982)', 'Terra is placed inside the Teen Titans as a plant by Deathstroke, and the Judas Contract is the story of how well the disguise holds.', 'Deceased', 'Evil', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_character (character_id, real_name, alias, universe_id, character_type, species, gender, first_appearance, origin, current_status, alignment, continuity, record_origin) VALUES (252, 'Malcolm Merlyn', 'Dark Archer', 2, 'Villain', 'Human', 'Male', 'Arrow (2012 television series)', 'The Arrowverse Malcolm Merlyn funds the Undertaking to level the Glades, and later becomes the League of Assassins problem everyone else has to solve.', 'Deceased', 'Evil', 'DC Comics (Arrowverse)', 'Canon');
INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (1, 'Avengers', 1, 1963, 'Avengers Mansion, New York City', 'Earth mightiest heroes, convened to face threats no single hero can survive.', 'Active', 'Marvel Comics (Earth-616)', 'Canon');
