INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (14, 'HYDRA (MCU)', 1, 1945, 'Mobile; embedded inside SHIELD', 'Infiltrate every institution, then use them. Cut off one head, two more take its place.', 'Dissolved', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (15, 'SHIELD (MCU)', 1, 1965, 'Triskelion, Washington, D.C.', 'The MCU agency that finds the strange before the public does.', 'Dissolved', 'Marvel Cinematic Universe (Earth-199999)', 'Canon');
