INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (29, 'League of Assassins', 2, 1971, 'Nanda Parbat', 'Ra''s al Ghul instruments of ecological and political purification.', 'Active', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (30, 'The Rogues', 2, 1956, 'Central City', 'Career criminals with a code: no killing unless the Flash forces it.', 'Active', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (31, 'A.R.G.U.S.', 2, 2012, 'Washington, D.C.', 'Advanced Research Group United Support: the state answer to metahuman security.', 'Active', 'DC Comics (New Earth/Prime Earth)', 'Canon');
INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (32, 'Justice League (DCEU)', 2, 2017, 'Hall of Justice (planned)', 'The DCEU League, formed in the shadow of Superman death and built to stop Steppenwolf.', 'Active', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (33, 'Task Force X (DCEU)', 2, 2016, 'Belle Reve Penitentiary, Louisiana', 'Amanda Waller expendable squad, collared and deniable.', 'Active', 'DCEU (Earth-1)', 'Canon');
INSERT INTO uni_team (team_id, team_name, universe_id, founding_year, headquarters, mission, team_status, continuity, record_origin) VALUES (34, 'Atlantean Royal Guard (DCEU)', 2, 2018, 'Atlantis', 'The crown military of Atlantis, sworn to the throne rather than to the surface.', 'Active', 'DCEU (Earth-1)', 'Canon');
