INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (1, 'Super strength', 'Physical', 'Lifts and strikes far beyond human limits; often expressed in hundreds of tonnes.', 9);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (2, 'Enhanced strength', 'Physical', 'Peak-human to low-superhuman lifting capacity, roughly two to ten times a strong adult.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (3, 'Invulnerability', 'Physical', 'Body resists penetration, impact and extreme temperature without lasting injury.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (4, 'Regeneration', 'Physical', 'Heals wounds rapidly; the limit is usually decapitation or total incineration.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (5, 'Super speed', 'Physical', 'Moves and reacts at multiples of the speed of sound.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (6, 'Flight', 'Physical', 'Sustained self-propelled flight, by wings, willpower or gravity control.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (7, 'Enhanced agility', 'Physical', 'Balance and acrobatic control beyond any gymnast.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (8, 'Enhanced reflexes', 'Physical', 'Reaction times measured in milliseconds.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (9, 'Enhanced senses', 'Physical', 'Hearing, smell or sight extended far past the human range.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (10, 'Size manipulation', 'Physical', 'Grows to building height or shrinks below the width of an atom.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (11, 'Shape-shifting', 'Physical', 'Alters form, mass and appearance, including the faces of others.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (12, 'Wall-crawling', 'Physical', 'Adheres to and climbs sheer surfaces using micro-scale grip.', 4);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (13, 'Density control', 'Physical', 'Raises or lowers personal density from intangible mist to armour-hard.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (14, 'Immortality', 'Physical', 'Does not age and reconstitutes after bodily destruction.', 9);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (15, 'Longevity', 'Physical', 'Ages very slowly; centuries of life without true immortality.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (16, 'Energy manipulation', 'Energy', 'Shapes raw power into blasts, shields and constructs at will.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (17, 'Energy projection', 'Energy', 'Fires concussive or cutting energy from hands, eyes or weapons.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (18, 'Energy absorption', 'Energy', 'Draws in external power and redirects or stores it.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (19, 'Force field generation', 'Energy', 'Projects barriers that stop bullets, blasts and pressure.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (20, 'Heat generation', 'Energy', 'Raises matter to ignition temperature on contact.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (21, 'Cold generation', 'Energy', 'Drains heat, freezing targets solid.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (22, 'Electrical manipulation', 'Energy', 'Generates and channels current strong enough to stun or kill.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (23, 'Light manipulation', 'Energy', 'Bends, concentrates and extinguishes visible light.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (24, 'Sound manipulation', 'Energy', 'Generates and shapes sonic force, including destructive resonance.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (25, 'Nuclear energy control', 'Energy', 'Channels fusion-scale energy; the highest output of any single body.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (26, 'Kinetic energy absorption', 'Energy', 'Soaks up impact and converts it into stored power.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (27, 'Gravity manipulation', 'Energy', 'Increases, reverses or cancels gravity in a local field.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (28, 'Magnetism manipulation', 'Energy', 'Commands all ferrous and electrically conductive matter.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (29, 'Weather manipulation', 'Energy', 'Summons storms, lightning, wind and pressure fronts.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (30, 'Telepathy', 'Mental', 'Reads, projects and edits thoughts across great distances.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (31, 'Telekinesis', 'Mental', 'Moves matter with the mind, from a coin to a continent.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (32, 'Mind control', 'Mental', 'Overrides a target will outright, sometimes for years.', 8);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (33, 'Mental resistance', 'Mental', 'Blocks intrusion, possession and illusion.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (34, 'Precognition', 'Mental', 'Sees probable futures; usually involuntary and partial.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (35, 'Empathy', 'Mental', 'Feels and projects emotion, including as a weapon.', 4);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (36, 'Illusion casting', 'Mental', 'Builds convincing sensory falsehoods in the target mind.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (37, 'Astral projection', 'Mental', 'Sends the consciousness out of the body onto the astral plane.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (38, 'Genius-level intelligence', 'Mental', 'Operates several fields at Nobel level before turning thirty.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (39, 'Tactical genius', 'Mental', 'Reads a battlefield and writes the counter-plan in seconds.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (40, 'Scientific genius', 'Mental', 'Invents and builds working advanced technology from scrap.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (41, 'Photographic memory', 'Mental', 'Recalls every page, face and coordinate exactly.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (42, 'Lie detection', 'Mental', 'Detects deception through physiological or telepathic cues.', 3);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (43, 'Magic', 'Mystical', 'Works structured spells by will, word and gesture.', 9);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (44, 'Dimensional manipulation', 'Mystical', 'Opens, collapses and reshapes other dimensions.', 9);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (45, 'Teleportation', 'Mystical', 'Moves instantly between known points.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (46, 'Portal creation', 'Mystical', 'Cuts stable doorways between places and realms.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (47, 'Exorcism', 'Mystical', 'Expels possessing entities and closes their footholds.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (48, 'Soul manipulation', 'Mystical', 'Takes, trades and restores souls as objects.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (49, 'Hellfire generation', 'Mystical', 'Summons flame that burns spirit as well as flesh.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (50, 'Power armour', 'Technological', 'Wears a powered exoskeleton that fights as well as it flies.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (51, 'Cybernetic enhancement', 'Technological', 'Body rebuilt or augmented with permanent hardware.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (52, 'Nanotechnology', 'Technological', 'Programmable matter that builds, heals and reforms on command.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (53, 'Technopathy', 'Technological', 'Commands machines and networks by direct neural link.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (54, 'Self-replication', 'Technological', 'Copies the self into independent bodies or drones.', 7);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (55, 'Piloting', 'Technological', 'Flies fixed-wing, rotary and exotic craft.', 3);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (56, 'Weapon mastery', 'Combat skill', 'Expert with every hand weapon, ancient to energy.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (57, 'Marksmanship', 'Combat skill', 'Hits a target the size of a coin at two hundred metres.', 4);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (58, 'Martial arts mastery', 'Combat skill', 'Several complete combat disciplines, taught and earned.', 6);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (59, 'Swordsmanship', 'Combat skill', 'Blade work at the level of a duelling champion.', 5);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (60, 'Archery mastery', 'Combat skill', 'Trick arrows and impossible shots as standard practice.', 4);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (61, 'Stealth mastery', 'Combat skill', 'Moves through occupied rooms unseen and unheard.', 4);
INSERT INTO uni_power (power_id, power_name, category, description, power_level) VALUES (62, 'Thief tradecraft', 'Combat skill', 'Locks, safes, alarms and a clean exit.', 4);
