INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (1, 'The Infinity Saga', 1, 'Film saga', 2008, 2019, 'The twenty-three film MCU arc from Tony Stark cave to the Snap and its reversal, told as one story about six stones and the people who would not leave them alone.', 'Thanos defeated; the Snap reversed; Stark and Romanoff dead', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (2, 'Secret Wars', 1, 'Comic event', 1984, 1985, 'The Beyonder pulls a selection of heroes and villains to Battleworld and offers the winner anything they want; the heroes win by not playing.', 'Battleworld destroyed; heroes returned to Earth', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (3, 'Civil War', 1, 'Comic event', 2006, 2007, 'A school explosion forces the Superhuman Registration Act; the hero community splits between Captain America refusal and Iron Man enforcement.', 'Registration enforced; Captain America surrendered and was assassinated later', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (4, 'The Infinity Gauntlet', 1, 'Comic event', 1991, 1991, 'Thanos assembles all six Infinity Gems and erases half the universe to court Death; the surviving heroes and cosmic entities counter-attack.', 'Gauntlet taken by Nebula, then by Adam Warlock; the Snap reversed', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (5, 'The Dark Phoenix Saga', 1, 'Comic arc', 1980, 1980, 'Jean Grey is corrupted by the Hellfire Club and the Phoenix Force, consumes a star and a planet, and the X-Men must decide whether to save or execute her.', 'Jean Grey sacrificed herself on the moon', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (6, 'Days of Future Past', 1, 'Comic arc', 1981, 1981, 'A Sentinel-ruled future sends Kate Pryde mind back into her younger self to stop the assassination that started the war.', 'Assassination prevented; future timeline averted', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (7, 'Age of Apocalypse', 1, 'Comic event', 1995, 1996, 'Legion kills Xavier in the past, and the world he returns to is one where Apocalypse has ruled for twenty years and the X-Men were founded by Magneto.', 'Timeline restored; Apocalypse defeated in the altered present', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (8, 'House of M', 1, 'Comic event', 2005, 2005, 'Wanda Maximoff rewrites reality into a mutant-ruled world where her family is whole; the heroes who remember it have to ask her to stop.', 'Reality restored; mutants reduced to a few hundred', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (9, 'Secret Invasion', 1, 'Comic event', 2008, 2008, 'The Skrull Empire has been replacing heroes and officials for years; the invasion begins with a SHIELD helicarrier crashing into Central Park.', 'Skrull invasion defeated; Norman Osborn put in charge of national security', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (10, 'Planet Hulk', 1, 'Comic arc', 2006, 2007, 'The Illuminati exile the Hulk to an uninhabited world; he lands on Sakaar instead and fights his way from gladiator to king.', 'Hulk crowned king of Sakaar, then returned to Earth for revenge', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (11, 'The Kree-Skrull War', 1, 'Comic event', 1971, 1972, 'The Kree and Skrull empires bring their war to Earth, with the Avengers caught between SHIELD, the Inhumans and a pacifist Kree captain.', 'War averted on Earth by the Avengers and the Inhuman royal family', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (12, 'Weapon X', 1, 'Comic arc', 1991, 1991, 'The Weapon X programme binds Wolverine to an operating table and coats his skeleton in Adamantium, erasing his memory and producing their perfect weapon.', 'Wolverine escaped; the programme continued', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (13, 'Dark Reign', 1, 'Comic event', 2008, 2009, 'Norman Osborn is given control of national security after the Skrull invasion and rebuilds SHIELD as HAMMER with villains in every uniform.', 'Osborn regime collapsed at the Siege of Asgard', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (14, 'Siege of Asgard', 1, 'Comic event', 2010, 2010, 'Osborn invades the floating Asgard over Oklahoma with HAMMER and a stolen Sentry, and the Avengers must defend a city that is also a god.', 'Osborn defeated; Asgard rebuilt; the Heroic Age began', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (15, 'Demon in a Bottle', 1, 'Comic arc', 1979, 1979, 'An armour malfunction and a takeover of Stark International push Tony Stark into alcoholism, and the arc is about the armoured hero admitting he cannot fix himself.', 'Stark accepted he was an alcoholic and sought help', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (16, 'Born Again', 1, 'Comic arc', 1986, 1986, 'The Kingpin learns Daredevil identity and dismantles his life piece by piece — licence, home, mind — and Matt Murdock rebuilds from nothing.', 'Murdock rebuilt and defeated the Kingpin scheme', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (17, 'Avengers: Infinity War', 1, 'Film saga', 2018, 2018, 'Thanos takes the stones across four fronts, and the Avengers lose every one of them. The film ends with the Snap.', 'Thanos won; half of all life erased', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (18, 'Avengers: Endgame', 1, 'Film saga', 2019, 2019, 'The surviving Avengers use the Quantum Realm to borrow the stones from the past, and the final battle is fought by everyone they brought back.', 'Snap reversed; Thanos killed; Stark and Romanoff dead', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (19, 'Captain America: Civil War', 1, 'Film saga', 2016, 2016, 'The Sokovia Accords split the Avengers, and Zemo uses a HYDRA file to make the split about Bucky Barnes and Howard Stark instead of policy.', 'Avengers fractured; the Accords enforced; Zemo imprisoned', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (20, 'Thor: Ragnarok', 1, 'Film saga', 2017, 2017, 'Hela takes Asgard, Thor is stranded on Sakaar, and the only way to stop her is to destroy the place he is trying to save.', 'Asgard destroyed; Hela dead; the Asgardians fled to Earth', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (21, 'The Westview Anomaly', 1, 'Television saga', 2021, 2021, 'Wanda Maximoff creates a sitcom reality around her grief in Westview, and SWORD, Agatha Harkness and the townspeople all try to end it.', 'The Hex collapsed; Wanda left as the Scarlet Witch', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (22, 'The Time Variance Authority', 1, 'Television saga', 2021, 2021, 'A Loki variant is arrested by the TVA and discovers the organisation maintaining a single sacred timeline, and the man who is actually running it.', 'The sacred timeline branched; Loki took a throne at the end of time', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (23, 'The Multiverse Saga', 1, 'Film saga', 2021, 2025, 'The MCU arc from the Hex to the Kang dynasty: every spell, portal and variant that opened the multiverse and the councils trying to police it.', 'Ongoing; the multiverse is unstable', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (24, 'The Black Order Assault', 1, 'Film saga', 2018, 2018, 'The children of Thanos hit New York, Edinburgh and Wakanda in sequence to take the Time and Mind Stones.', 'Stones taken; the Order destroyed', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (25, 'X-Men: The Dark Phoenix', 1, 'Film saga', 2006, 2006, 'The X-Men film continuity retells the Phoenix story as Jean Grey losing control of a cosmic force, with the team splitting over whether to save her.', 'Jean Grey killed and the school reopened', 'Marvel Comics (X-Men Film Series)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (26, 'The Hand War', 1, 'Television saga', 2017, 2017, 'Four street-level heroes discover the Hand is digging under New York for a substance that will raise the dead, and that Elektra is leading it.', 'The Hand defeated; Midland Circle collapsed', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (27, 'Secret Wars (2015)', 1, 'Comic event', 2015, 2015, 'The final incursion destroys the Marvel multiverse and Doctor Doom rebuilds what is left as Battleworld, ruling it as God-Emperor.', 'Multiverse restored; Reed Richards rebuilt reality', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (28, 'The Accord Crisis', 1, 'Crossover', 2020, 2021, 'Original addition — a registration-style dispute between unaffiliated heroes and a metahuman authority, written for this demonstration as a small-scale civil-war analogue.', 'Negotiated settlement; the Vigil Accord formed', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (29, 'Crisis on Infinite Earths', 2, 'Comic event', 1985, 1986, 'The Anti-Monitor destroys the multiverse one Earth at a time, and the surviving heroes fight a war across collapsing realities.', 'Multiverse collapsed into one Earth; the Flash and Supergirl died', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (30, 'Flashpoint', 2, 'Comic event', 2011, 2011, 'Barry Allen saves his mother and creates a timeline where Atlantis and Themyscira are at war, Superman was never raised free and Bruce Wayne died instead of his father.', 'Timeline restored; the New 52 began', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (31, 'Knightfall', 2, 'Comic arc', 1993, 1994, 'Bane wears Batman down over months and breaks his back, and Gotham is handed to Azrael until Bruce Wayne takes it back.', 'Batman recovered; Bane defeated; Azrael removed', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (32, 'The Death of Superman', 2, 'Comic arc', 1992, 1993, 'Doomsday fights its way across America to Metropolis, and Superman dies stopping it. The funeral issues are the point of the story.', 'Doomsday killed; Superman resurrected months later', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (33, 'The Dark Knight Returns', 2, 'Comic arc', 1986, 1986, 'A retired Bruce Wayne puts the cowl back on at fifty-five, and the story is about whether Batman was ever anything but a necessary monster.', 'Batman faked his death and trained a new generation', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (34, 'Batman: The Killing Joke', 2, 'Comic arc', 1988, 1988, 'The Joker shoots Barbara Gordon, kidnaps Jim Gordon and tries to prove that one bad day is all it takes to make anyone into him.', 'Barbara paralysed; the argument left unresolved', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (35, 'A Death in the Family', 2, 'Comic arc', 1988, 1989, 'Jason Todd goes looking for his mother and finds the Joker instead; the readers voted for the ending.', 'Jason Todd killed; the Joker escaped', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (36, 'The Long Halloween', 2, 'Comic arc', 1996, 1997, 'A year-long murder mystery in which a Holiday killer takes one victim a month and the answer turns out to be the district attorney.', 'Two-Face created; the Falcone family broken', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (37, 'Hush', 2, 'Comic arc', 2002, 2003, 'An old friend orchestrates a year of attacks on Batman using every villain in Gotham, and the case ends with Catwoman and Batman closer than ever.', 'Hush defeated; the Riddler revealed as the architect', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (38, 'Tower of Babel', 2, 'Comic arc', 2000, 2000, 'Ra al Ghul steals Batman contingency plans for every Justice League member and uses them one by one, which is worse than beating them.', 'League freed; Batman expelled from the team', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (39, 'Blackest Night', 2, 'Comic event', 2009, 2010, 'The Black Lantern rings raise the dead across the universe and every Corps has to fight its own casualties.', 'Black Lanterns defeated; the White Lantern entity appeared', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (40, 'The Sinestro Corps War', 2, 'Comic event', 2007, 2007, 'Sinestro builds a fear-powered Corps on Qward and attacks Oa, and the Guardians respond by rewriting their own laws.', 'Sinestro captured; the Guardians authorised lethal force', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (41, 'Infinite Crisis', 2, 'Comic event', 2005, 2006, 'Alexander Luthor and Superboy-Prime pull Earth-Two back into existence and try to rebuild a single perfect Earth out of the survivors.', 'Multiverse restored; Superboy-Prime imprisoned', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (42, 'The Darkseid War', 2, 'Comic event', 2015, 2016, 'Darkseid and the Anti-Monitor fight a war across the multiverse with the Justice League as instruments, and Batman ends up sitting in a Mobius Chair.', 'Anti-Monitor defeated; Darkseid killed; Batman briefly omniscient', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (43, 'Kingdom Come', 2, 'Comic arc', 1996, 1996, 'A future in which the Justice League has retired and a new generation of heroes has started killing; the old guard returns to stop the war.', 'Nuclear detonation; the League rebuilt the world afterwards', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (44, 'Batman: No Mans Land', 2, 'Comic arc', 1999, 2000, 'An earthquake levels Gotham, the government abandons it and the city becomes a year-long territory war run by its own villains.', 'Gotham rebuilt; Batman returned to the city', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (45, 'The Judas Contract', 2, 'Comic arc', 1984, 1984, 'Terra is a mole inside the Teen Titans working for Deathstroke, and the team is picked apart from the inside.', 'Terra killed; Deathstroke defeated; the team rebuilt', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (46, 'Task Force X: Belle Reve', 2, 'Comic arc', 1987, 1988, 'Amanda Waller builds a squad of convicts with explosive collars and sends them on the missions the Justice League would refuse to authorise.', 'Programme continued despite the body count', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (47, 'The Legion of Doom', 2, 'Comic event', 1978, 1979, 'A villain coalition organised against the Justice League itself, and the first time the League had to fight an enemy that planned like they did.', 'League broke the coalition; several members imprisoned', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (48, 'The Steppenwolf Invasion', 2, 'Film saga', 2017, 2017, 'Steppenwolf collects the three Mother Boxes on Earth, and the newly formed League has to stop him before Apokolips has a bridge.', 'Steppenwolf killed; the Mother Boxes separated', 'DCEU (Earth-1)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (49, 'The Battle of Metropolis', 2, 'Film saga', 2013, 2013, 'Zod terraforms Earth into Krypton above Metropolis, and Superman has to destroy his own species to stop it.', 'Zod killed; Metropolis levelled; Superman revealed', 'DCEU (Earth-1)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (50, 'The Midway City Mission', 2, 'Film saga', 2016, 2016, 'Amanda Waller sends Task Force X into a city taken over by Enchantress to recover a high-value asset, and loses two members doing it.', 'Enchantress defeated; the Squad honoured unofficially', 'DCEU (Earth-1)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (51, 'The War for the Throne of Atlantis', 2, 'Film saga', 2018, 2018, 'Orm declares war on the surface and Arthur Curry has to win a trident and a duel to stop him.', 'Orm deposed; Arthur crowned; the war called off', 'DCEU (Earth-1)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (52, 'The Undertaking', 2, 'Television saga', 2013, 2013, 'Malcolm Merlyn plans to level the Glades with a seismic device, and Oliver Queen has to stop it with a bow and a small team.', 'Device partially detonated; the Glades destroyed', 'DC Comics (Arrowverse)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (53, 'The Savitar Saga', 2, 'Television saga', 2016, 2017, 'Team Flash fights a speedster god who turns out to be a future version of Barry Allen, and the only way to win is to let him erase himself.', 'Savitar erased; Iris survived', 'DC Comics (Arrowverse)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (54, 'Vandal Savage and the Time Masters', 2, 'Television saga', 2016, 2016, 'Rip Hunter assembles the Legends to stop Vandal Savage from rewriting history, and discovers the Time Masters were never on their side.', 'Savage defeated; the Time Masters dissolved', 'DC Comics (Arrowverse)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (55, 'The Meteor Shower Years', 2, 'Television saga', 2001, 2011, 'Clark Kent grows up in Smallville hiding what he is while kryptonite-powered threats and Lex Luthor friendship collapse around him.', 'Clark accepted the cape; Lex became the enemy', 'DC Comics (Smallville continuity)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (56, 'The Lantern Relief Accord', 2, 'Crossover', 2021, 2022, 'Original addition — a disaster-relief pact between unaffiliated heroes and two Lantern sectors, written for this demonstration as a small-scale coordination exercise.', 'Accord signed; the Blue Lantern Circle formed', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (57, 'The Kang Dynasty', 1, 'Film saga', 2023, 2025, 'The MCU council of Kangs begins moving between branches after the sacred timeline ends, and the Avengers franchise is rebuilt around stopping them.', 'Ongoing; the multiverse is unmanaged', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (58, 'The Avengers: Standoff', 1, 'Comic event', 2016, 2016, 'SHIELD replaces the town of Pleasant Hill with a prison for supervillains whose minds have been rewritten, and the heroes find out from the inside.', 'Pleasant Hill exposed; trust in SHIELD broken again', 'Marvel Comics (Earth-616)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (59, 'Trinity War', 2, 'Comic event', 2013, 2013, 'A murder with a Justice League weapon turns the League, Justice League Dark and the Justice League of America against each other.', 'The factions fractured; the Crime Syndicate followed', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_mission (mission_id, mission_name, universe_id, storyline_category, start_year, end_year, description, outcome, continuity) VALUES (60, 'Forever Evil', 2, 'Comic event', 2013, 2014, 'The Crime Syndicate of Earth-3 replaces the Justice League and the villains of Earth have to save it, which is the joke and the point.', 'Crime Syndicate defeated; the League restored', 'DC Comics (New Earth/Prime Earth)');
