INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (19, 57, 4, 'Cosmic counter-attack', 'Led the assault on Thanos', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (20, 6, 4, 'Magic support', 'Coordinated the mystic front', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (21, 5, 4, 'Field support', 'Survived the initial Snap by chance', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (22, 73, 4, 'Opportunist', 'Claimed the gauntlet briefly', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (23, 32, 5, 'Phoenix host', 'Died on the moon by her own choice', 'Killed');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (24, 31, 5, 'Team leader', 'Refused to let the team kill her', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (25, 11, 5, 'Field operative', 'Argued for execution and was overruled', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (26, 38, 5, 'Antagonist', 'Hellfire Club manipulation of the Phoenix', 'Survived');
