INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (28, 11, 6, 'Future resistance', 'Held the camp line', 'Killed');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (29, 30, 6, 'Future resistance', 'Covered the escape', 'Killed');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (30, 29, 6, 'Strategy', 'Planned the mind transfer', 'Killed');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (31, 54, 7, 'Antagonist', 'Ruled the altered world for twenty years', 'Killed');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (32, 12, 7, 'Founder of the altered X-Men', 'Drove the resistance', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (33, 11, 7, 'Field operative', 'One-handed, still the best there is', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (34, 31, 7, 'Field leader', 'Led the raid on Apocalypse', 'Killed');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (35, 28, 7, 'Altered X-Men member', 'Fought alongside the team', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (36, 7, 8, 'Reality warper', 'Restored reality and decimated mutantkind', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (37, 12, 8, 'Putative ruler', 'Lost his children and his world', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (38, 29, 8, 'Opposition', 'Led the attempt to stop her', 'Killed');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (39, 199, 8, 'Instigator', 'Pushed Wanda into the rewrite', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (40, 6, 8, 'Opposition', 'Broke the illusion from within', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (41, 14, 9, 'Underground coordinator', 'Ran the resistance from a hidden base', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (42, 1, 9, 'Technology', 'Built the detection system that ended it', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (43, 22, 9, 'Infiltration', 'Rooted out the replaced agents', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (44, 232, 9, 'Antagonist', 'Skrull queen, defeated in Central Park', 'Killed');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (45, 4, 10, 'Protagonist', 'Became king of Sakaar', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (46, 57, 10, 'Cosmic observer', 'Warned Earth of the return', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (47, 1, 10, 'Responsible party', 'Voted for the exile', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (48, 6, 10, 'Responsible party', 'Voted for the exile', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (49, 18, 11, 'Kree defector', 'Turned against his own empire', 'Survived');
INSERT INTO uni_mission_participation (participation_id, character_id, mission_id, role, outcome, survival_status) VALUES (50, 194, 11, 'Inhuman king', 'Refused to give up his people', 'Survived');
