INSERT INTO uni_organization (organization_id, organization_name, universe_id, organization_type, headquarters, leader_character_id, objectives, continuity, record_origin) VALUES (1, 'SHIELD', 1, 'Intelligence agency', 'Triskelion, Washington, D.C.', 14, 'Detect and contain superhuman and extraterrestrial threats before the public is aware of them.', 'Marvel Comics (Earth-616)', 'Canon');
