INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (70, 'Waverley Station Ambush', 1, 'Edinburgh', 2018, 'Proxima Midnight and Corvus Glaive ambush Wanda and Vision at a railway station.', 'Vision wounded; Avengers intervene', 0, 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (71, 'Knowhere Dismantling', 1, 'Knowhere', 2023, 'The Guardians return to a ruined Knowhere and rebuild it as a home, which is the nearest thing to a battle in it.', 'Guardians (rebuilt)', 0, 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (72, 'Counter-Earth Assault', 1, 'Counter-Earth', 2023, 'The Guardians assault the High Evolutionary laboratory to free his experiments.', 'Guardians', 0, 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (73, 'Illuminati Hall Breach', 1, 'Earth-838', 2022, 'The Scarlet Witch walks into the Illuminati hall and kills every member in it.', 'Scarlet Witch', 0, 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (74, 'Mount Wundagore Collapse', 1, 'Mount Wundagore', 2022, 'Wanda destroys the Darkhold and brings the mountain down on herself.', 'Draw (Wanda presumed dead)', 0, 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (75, 'Daily Planet Siege', 2, 'Daily Planet, Metropolis', 2016, 'Doomsday lands on the Daily Planet building and the Trinity has to take it down in the city.', 'Trinity', 0, 'DCEU (Earth-1)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (76, 'Stryker Base Assault', 1, 'Three Mile Island', 2003, 'The X-Men and Magneto Brotherhood assault Stryker base under the dam.', 'X-Men and Brotherhood (temporary alliance)', 0, 'Marvel Comics (X-Men Film Series)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (77, 'Liberty Island Defection', 2, 'Liberty Island', 2017, 'Wonder Woman, Batman and Steve Trevor fight Ares above a burning airfield in Belgium.', 'Wonder Woman', 0, 'DCEU (Earth-1)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (78, 'Corto Maltese Assault', 2, 'Corto Maltese', 2021, 'Two Suicide Squad elements assault Jotunheim to destroy Project Starfish.', 'Task Force X (mostly)', 0, 'DCEU (Earth-1)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (79, 'Belle Reve Breakout', 2, 'Belle Reve Penitentiary, Louisiana', 2016, 'The Squad fights its way out of a prison it was never meant to leave.', 'Task Force X', 0, 'DCEU (Earth-1)');
INSERT INTO uni_battle (battle_id, battle_name, universe_id, location, year, description, winner, casualties, continuity) VALUES (80, 'Glades Riot', 2, 'The Glades, Star City', 2012, 'A riot engineered to cover a kidnapping turns into a street war with a vigilante in the middle.', 'Team Arrow (partial)', 0, 'DC Comics (Arrowverse)');
