INSERT INTO uni_battle_participation (participation_id, battle_id, character_id, side, battle_result, status) VALUES (414, 80, 213, 'Team Arrow and allies', 'Victorious', 'Survived');
INSERT INTO uni_battle_participation (participation_id, battle_id, character_id, side, battle_result, status) VALUES (415, 80, 142, 'Team Arrow and allies', 'Victorious', 'Survived');
INSERT INTO uni_battle_participation (participation_id, battle_id, character_id, side, battle_result, status) VALUES (416, 80, 215, 'Team Arrow and allies', 'Victorious', 'Survived');
INSERT INTO uni_battle_participation (participation_id, battle_id, character_id, side, battle_result, status) VALUES (417, 80, 252, 'League of Assassins', 'Defeated', 'Survived');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (1, 83, 99, 'Enemies', 'The defining antagonism of Gotham: Batman refuses to kill him and the Joker builds a career on that refusal.', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (2, 3, 8, 'Adoptive brothers', 'Raised as brothers in Asgard; the love is real and so is every betrayal.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (3, 1, 2, 'Allies with ideological conflict', 'Friends who disagree about accountability so completely that it splits the Avengers.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (4, 84, 109, 'Enemies', 'Luthor needs Superman to be the obstacle to human greatness, and Superman keeps refusing to be one.', 'DC Comics (New Earth/Prime Earth)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (5, 5, 6, 'Allies', 'Occasional partners in New York, on cases that are equally likely to be mystical or criminal.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (6, 12, 29, 'Old friends turned enemies', 'Two survivors who agree on the danger and disagree on everything about the response.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (7, 11, 28, 'Enemies', 'A century of shared history, most of it violent, and neither can kill the other permanently.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (8, 31, 32, 'Romantic partners', 'Married X-Men leaders whose relationship survived the Phoenix and did not survive everything else.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (9, 7, 24, 'Romantic partners', 'A synthezoid and a magic user married, built a family out of nothing, and lost it twice.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (10, 68, 73, 'Adoptive sisters', 'Both raised by Thanos, both damaged by it, and neither willing to admit the other is family.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (11, 67, 68, 'Romantic partners', 'Guardians teammates whose partnership runs on mutual competence and terrible timing.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (12, 9, 69, 'Enemies', 'Drax was literally created to kill Thanos after Thanos killed his family.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (13, 70, 71, 'Best friends', 'The loudest and the quietest Guardian, and the one pair that never needed a plan.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (14, 40, 42, 'Romantic partners and rivals', 'Daredevil great love and most reliable opponent, often in the same week.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (15, 40, 43, 'Enemies', 'The Kingpin dismantled Matt Murdock life by name and licence, which was worse than beating him.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (16, 43, 51, 'Employer and assassin', 'Fisk keeps the most reliable killer in New York on retainer and treats him as a tool.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (17, 5, 44, 'Enemies', 'The Goblin is the enemy who took the most from Peter Parker and kept coming back.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (18, 5, 45, 'Enemies', 'The first villain who beat Spider-Man outright, and the one who later tried to be him.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (19, 5, 46, 'Enemies turned uneasy allies', 'The symbiote was Peter first, and Eddie Brock has never entirely forgiven either of them.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (20, 5, 25, 'Counterparts', 'Two Spider-People from different universes; the same loss, told twice.', 'Marvel Comics (Earth-65)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (21, 5, 26, 'Mentor and successor', 'Peter trained Miles, then Miles had to carry the name without him.', 'Marvel Comics (Earth-1610)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (22, 2, 20, 'Best friends', 'Steve Rogers refuses to stop looking for Bucky Barnes through seventy years and two identities.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (23, 1, 23, 'Best friends', 'Rhodes is the one person Tony Stark listens to before the situation becomes a crisis.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (24, 1, 5, 'Mentor and protégé', 'Stark recruited a teenager, tried to mentor him, and mostly taught him what not to accept.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (25, 21, 22, 'Partners', 'Clint Barton was sent to kill Natasha Romanoff and made a different call.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (26, 16, 17, 'Founding partners', 'Co-founders of the Avengers who also built and rebuilt a relationship.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (27, 17, 24, 'Creator and creation', 'Ultron made Vision; Pym made Ultron, and the guilt follows the whole family.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (28, 1, 4, 'Rivals', 'Friends, colleagues and the two most intellectually arrogant people in the room.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (29, 3, 4, 'Old rivals', 'Contested the arena on Sakaar and have contested most things since.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (30, 9, 57, 'Enemies', 'The Surfer was herald to Galactus and has been the one who kept returning to stop Thanos.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (31, 9, 56, 'Cosmic rivals', 'Two cosmic-scale appetites that have collided over the same planets.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (32, 6, 59, 'Mystical enemies', 'Strange won a fight by refusing to lose it, which Dormammu has not forgotten.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (33, 6, 248, 'Teacher and student', 'The Ancient One trained Strange into a role he was not ready to inherit.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (34, 11, 29, 'Mentor and student', 'Xavier gave Wolverine a place that did not require him to be useful, which is the closest he has had to a home.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (35, 11, 39, 'Mentor and student', 'The pairing that taught Kitty how to be an X-Man and taught Logan how to teach.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (36, 11, 31, 'Rivals', 'Two field leaders with incompatible methods and shared custody of one team.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (37, 31, 38, 'Romantic partners', 'A relationship built after Jean Grey death and dissolved around its own compromises.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (38, 13, 30, 'Romantic partners', 'Married for a time in Wakanda, a match between two leaders who each had a country first.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (39, 11, 37, 'Friends', 'Two X-Men who found the same unlikely stability in the team.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (40, 36, 39, 'Romantic partners', 'Long on-and-off relationship between two founding members.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (41, 34, 35, 'Romantic partners', 'Two thieves who both had to learn how to be trusted.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (42, 27, 28, 'Allies', 'Brotherhood accomplices, and no more loyal to each other than to Magneto.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (43, 27, 38, 'Rivals', 'Two women who have run the same organisations and neither trusts the other with them.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (44, 62, 63, 'Allies', 'Midnight Sons colleagues who disagree about what to do with a soul once they have it.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (45, 5, 64, 'Enemies turned allies', 'A villain by hunger and an ally by choice.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (46, 65, 66, 'Partners', 'Two runaway teenagers whose powers were made from the same experiment and only work together.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (47, 194, 195, 'Spouses', 'King and queen of the Inhumans; she speaks for him because he cannot speak at all.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (48, 190, 191, 'Spouses', 'The founding couple of the Fantastic Four, and the ones who keep it a family.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (49, 192, 193, 'Adoptive siblings', 'Ben Grimm and Johnny Storm are the brothers neither of them expected.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (50, 27, 37, 'Parent and child', 'Mystique is Kurt Wagner mother, a fact neither of them mentions first.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (51, 200, 202, 'Spouses', 'Married, raising a daughter, and still the two most stubborn people in New York.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (52, 200, 201, 'Best friends', 'Heroes for Hire: the partnership that predates the team.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (53, 40, 41, 'Ideological enemies', 'Both from Hell Kitchen, both orphans of violence, with opposite conclusions about killing.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (54, 5, 48, 'Enemies', 'A villain whose power is exactly the one Spider-Man cannot touch.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (55, 5, 47, 'Enemies turned uneasy allies', 'A career criminal who has tried to go straight more than once.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (56, 5, 49, 'Enemies', 'A special-effects artist with a grudge and no need for actual powers.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (57, 5, 50, 'Enemies', 'The hunter who regards Spider-Man as the only prey worth a lifetime.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (58, 10, 76, 'Rivals', 'The one person whose skills Wade Wilson cannot copy, and who has no patience for the joke.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (59, 10, 11, 'Rivals', 'A friendship built entirely on violence and refusal to die, which suits both of them.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (60, 8, 60, 'Adoptive siblings', 'Hela and Loki are the two Asgardian children Odin could not control, for different reasons.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (61, 24, 53, 'Creator and creation', 'Ultron built Vision to be a weapon, and Vision chose the Avengers instead.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (62, 17, 53, 'Creator and creation', 'Pym built Ultron, and it has never stopped being his worst decision.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (63, 54, 55, 'Creator and creation', 'Apocalypse remade Nathaniel Essex, and Sinister has been serving and betraying that bargain for a century.', 'Marvel Comics (Earth-616)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (64, 146, 147, 'Allies with ideological conflict', 'Signed the Accords, then fought his friend over a HYDRA file and a 1991 winter road.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (65, 148, 153, 'Adoptive brothers', 'Fifteen hundred years of brotherhood, one death by Thanos, and one variant who never had it.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (66, 154, 156, 'Adoptive father and daughter', 'Raised as a weapon, loved in his own way, traded for a stone.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (67, 154, 218, 'Adoptive father and daughter', 'Rebuilt after every defeat and never forgiven for one of them.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (68, 155, 156, 'Romantic partners', 'A relationship that ends twice: once at Vormir and once with a version who does not remember it.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (69, 158, 159, 'Best friends', 'A raccoon who cannot say it and a tree who can only say his own name.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (70, 146, 150, 'Mentor and protégé', 'Tony Stark recruited a fifteen-year-old and spent three films learning how much that cost.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (71, 151, 152, 'Rivals', 'He watched fourteen million futures and she decided she would rather have one of her own.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (72, 166, 237, 'Romantic partners', 'The Hex is a love letter written in an entire town.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (73, 160, 217, 'Allies', 'Her pager is the reason the Avengers found her at all.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (74, 160, 161, 'Recruited', 'Fury gave her a job and a way to clear the ledger; she gave him a decade of loyalty.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (75, 161, 162, 'Partners', 'The same call Barton made in Budapest, told twice.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (76, 153, 233, 'Counterparts', 'Two variants of the same person who disagree about whether anyone gets to choose the timeline.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (77, 153, 235, 'Enemies turned colleagues', 'One wrote the timeline; the other ended up holding the branches.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (78, 167, 169, 'Enemies', 'A moon-god servant and a death goddess have no reason to meet again.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (79, 168, 216, 'Cousins', 'Both sons of Wakanda, one raised in it and one sold by it.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (80, 152, 170, 'Enemies', 'He is the reason she left Sokovia, and the reason she had nothing to return to.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (81, 224, 225, 'Allies', 'The Black Order field pair: one talks and one arrives.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (82, 226, 227, 'Spouses', 'Married in the comic continuity and partners in the field in both.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (83, 220, 221, 'Reluctant allies', 'They share a client list, a borough and no patience whatsoever.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (84, 221, 222, 'Spouses', 'Two Defenders who married and kept the job.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (85, 222, 223, 'Heroes for Hire', 'A partnership that began as a business arrangement and became a friendship.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (86, 164, 165, 'Rivals turned partners', 'They argue about the shield for a whole miniseries and then share it.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (87, 152, 166, 'Aliases of the same person', 'The name she took in Westview and the one she was given by the Darkhold.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (88, 81, 82, 'Colleagues', 'Both worked for SHIELD; neither is a field agent by training.', 'Marvel Cinematic Universe (Earth-199999)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (89, 171, 172, 'Rivals turned allies', 'Two men who each decided the other was the danger, and who built the League after.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (90, 171, 234, 'Enemies', 'Zod is the last Kryptonian Superman had to kill to keep the planet.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (91, 171, 173, 'Allies', 'The two strongest arguments in the League, and they rarely disagree about the plan.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (92, 172, 174, 'Mentor and protégé', 'Bruce Wayne found Barry Allen before Barry had any idea what he was.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (93, 172, 176, 'Allies', 'Two people whose families were destroyed by the same institutions.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (94, 175, 182, 'Half-brothers', 'A surface-raised heir and an Atlantean king who cannot both be right.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (95, 175, 181, 'Romantic partners', 'The queen of Xebel and the king of Atlantis, in that order.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (96, 175, 238, 'Enemies', 'A submarine fight, a dead father, and a two-film grudge.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (97, 177, 179, 'Former partners', 'He is the relationship she leaves, and the film is about leaving it.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (98, 177, 178, 'Teammates', 'Two Task Force X members who each keep a photograph of a child where nobody can see it.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (99, 178, 180, 'Handler and asset', 'A collar, a promise about his daughter, and a director who would not hesitate.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (100, 177, 180, 'Handler and asset', 'Waller keeps the Squad on a collar and Harley on nothing but curiosity.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (101, 110, 183, 'Nephew and uncle', 'Steppenwolf is Darkseid general, and failed him on Earth.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (102, 182, 231, 'Mother and son', 'Everything Orm believes about the surface comes from losing her to it.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (103, 178, 229, 'Teammates', 'Squad colleagues by circumstance, never by preference.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (104, 173, 177, 'Allies', 'Foils in temperament and occasionally partners in a corridor.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (105, 111, 174, 'Enemies', 'A speedster who wants everything Barry has, including his mother alive.', 'DCEU (Earth-1)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (106, 142, 213, 'Partners', 'Diggle is the first person Oliver Queen trusted with the truth, and the one who kept telling it.', 'DC Comics (Arrowverse)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (107, 213, 215, 'Spouses', 'Team Arrow technical lead, then wife, then the reason the team exists at all.', 'DC Comics (Arrowverse)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (108, 213, 214, 'Romantic partners', 'On-again relationship that anchors both of them to Star City.', 'DC Comics (Arrowverse)');
INSERT INTO uni_relationship (relationship_id, character1_id, character2_id, relationship_type, description, continuity) VALUES (109, 142, 215, 'Teammates', 'The two people who talk Oliver out of his worst plans.', 'DC Comics (Arrowverse)');
